{"path": "/tmp/sv-30e6b6d37f3d4af1ac45e1a6de49821e/Components/Pages/Apply/StepIndicator.razor", "file_text": "@namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var stepNumber = i + 1;
            var status = GetStepStatus(stepIndex);
            <li class="step-item @status" @onclick="() => OnStepClick(stepIndex)">
                <span class="step-circle">
                    @if (status == "completed")
                    {
                        <span class="step-check">&#10003;</span>
                    }
                    else
                    {
                        @stepNumber
                    }
                </span>
                <span class="step-label">@StepNames[stepIndex]</span>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnNavigateToStep { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private string GetStepStatus(int index)
    {
        if (index == CurrentStep) return "active";
        if (index < CurrentStep) return "completed";
        return "future";
    }

    private async Task OnStepClick(int index)
    {
        if (index < CurrentStep)
        {
            await OnNavigateToStep.InvokeAsync(index);
        }
    }
}
"}

{"path": "/tmp/sv-30e6b6d37f3d4af1ac45e1a6de49821e/Components/Pages/Apply/PersonalInfoStep.razor", "file_text": "@namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    <div class="form-group">
        <label for="fullName">Full Name *</label>
        <input id="fullName" type="text" class="form-control" value="@FullName"
               @oninput="e => FullName = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="email">Email *</label>
        <input id="email" type="email" class="form-control" value="@Email"
               @oninput="e => Email = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="phone">Phone *</label>
        <input id="phone" type="tel" class="form-control" value="@Phone"
               @oninput="e => Phone = e.Value?.ToString() ?? string.Empty" />
    </div>

    <div class="form-group">
        <label for="address">Address *</label>
        <input id="address" type="text" class="form-control" value="@Address"
               @oninput="e => Address = e.Value?.ToString() ?? string.Empty" />
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span>Validating...</span>
            }
            else
            {
                <span>Next</span>
            }
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public string Address { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<(string FullName, string Email, string Phone, string Address)> OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string ErrorMessage = string.Empty;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Phone))
        {
            ErrorMessage = "Phone is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValidEmail = await ValidateEmail(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync((FullName, Email, Phone, Address));
    }
}
"}

