@namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" class="form-control" value="@Name"
               @oninput="e => { Name = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" value="@Relationship"
               @oninput="e => { Relationship = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Email"
               @oninput="e => { Email = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Phone"
               @oninput="e => { Phone = e.Value?.ToString() ?? string.Empty; NotifyChanged(); }" />
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = string.Empty;
    [Parameter] public string Relationship { get; set; } = string.Empty;
    [Parameter] public string Email { get; set; } = string.Empty;
    [Parameter] public string Phone { get; set; } = string.Empty;
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

@namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var refEntry = References[index];
        <ReferenceForm Index="index"
                       Name="@refEntry.Name"
                       Relationship="@refEntry.Relationship"
                       Email="@refEntry.Email"
                       Phone="@refEntry.Phone"
                       CanRemove="@(References.Count > 2)"
                       OnRemove="() => RemoveReference(index)"
                       OnChanged="data => UpdateReference(index, data)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceViewModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceViewModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string ErrorMessage = string.Empty;

    protected override void OnInitialized()
    {
        while (References.Count < 2)
        {
            References.Add(new ReferenceViewModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceViewModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < References.Count)
        {
            References[index] = new ReferenceViewModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceViewModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

