@namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply

<div class="step-content">
    <h2>Cover Letter</h2>

    <div class="form-group">
        <label for="coverLetter">Write your cover letter below:</label>
        <textarea id="coverLetter" class="form-control cover-letter-textarea" rows="12"
                  maxlength="2000"
                  value="@CoverLetter"
                  @oninput="e => CoverLetter = e.Value?.ToString() ?? string.Empty"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string ErrorMessage = string.Empty;

    private async Task HandleNext()
    {
        ErrorMessage = string.Empty;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "A cover letter is required.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

