arguments.file_text:
namespace sv_30e6b6d37f3d4af1ac45e1a6de49821e.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@using sv_30e6b6d37f3d4af1ac45e1a6de49821e.Models
@using sv_30e6b6d37f3d4af1ac45e1a6de49821e.Components.Pages.Apply
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="HandlePersonalNext" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep FullName="@personalFullName"
                        Email="@personalEmail"
                        Phone="@personalPhone"
                        Address="@personalAddress"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnBack="GoBack"
                        OnEditStep="NavigateToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep = 0;

    // Personal Info state
    private string personalFullName = string.Empty;
    private string personalEmail = string.Empty;
    private string personalPhone = string.Empty;
    private string personalAddress = string.Empty;

    // Work History state
    private List<WorkHistoryStep.WorkEntryViewModel> workEntries = new();

    // References state
    private List<ReferencesStep.ReferenceViewModel> references = new();

    // Cover Letter state
    private string coverLetter = string.Empty;

    private void NavigateToStep(int step)
    {
        if (step >= 0 && step <= 4)
        {
            currentStep = step;
        }
    }

    private void GoBack()
    {
        if (currentStep > 0)
        {
            currentStep--;
        }
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        personalFullName = data.FullName;
        personalEmail = data.Email;
        personalPhone = data.Phone;
        personalAddress = data.Address;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryViewModel> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceViewModel> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(personalFullName, personalEmail, personalPhone, personalAddress);
        var workHistory = new WorkHistory(workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList());
        var refs = references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(personal, workHistory, refs, coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-container {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-container h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    position: relative;
    cursor: default;
}

.step-item.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    margin-bottom: 0.5rem;
}

.step-item.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-item.future .step-circle {
    opacity: 0.5;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.step-item.future .step-label {
    opacity: 0.5;
}

.step-check {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #333;
}

.step-description {
    color: #666;
    margin-bottom: 1rem;
}

/* Form Elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: 500;
    color: #333;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-control:disabled {
    background: #f5f5f5;
    color: #999;
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-row .form-group {
    flex: 1;
}

.form-check {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.form-check input[type="checkbox"] {
    width: auto;
}

.form-check label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Buttons */
.btn {
    padding: 0.6rem 1.25rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    border: none;
    font-weight: 500;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ccc;
    color: #333;
}

.btn-outline:hover {
    background: #f5f5f5;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-danger:hover {
    background: #bb2d3b;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #0b5ed7;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Step Actions */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #e0e0e0;
}

/* Error Message */
.error-message {
    color: #dc3545;
    background: #f8d7da;
    border: 1px solid #f5c6cb;
    border-radius: 4px;
    padding: 0.75rem 1rem;
    margin-top: 1rem;
}

/* Work Entry Card */
.work-entry-card, .reference-card {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header, .reference-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h4, .reference-header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 200px;
    resize: vertical;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.25rem;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #e0e0e0;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.review-data {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-data dt {
    font-weight: 500;
    color: #666;
}

.review-data dd {
    margin: 0;
}

.review-work-entry {
    margin-bottom: 0.75rem;
    padding: 0.5rem 0;
}

.review-dates {
    font-size: 0.9rem;
    color: #666;
}

.review-reference {
    margin-bottom: 0.5rem;
}

.review-cover-letter {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    border: 1px solid #e0e0e0;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.submission-confirmation h3 {
    color: #198754;
    font-size: 1.5rem;
}

